<script setup lang="ts">import{onMounted,ref}from'vue';import{getInfrastructure,getRuntimeMetrics}from'@/api/client';import type{InfrastructureResponse,RuntimeMetricsSnapshot}from'@/types';const infra=ref<InfrastructureResponse>();const metrics=ref<RuntimeMetricsSnapshot>();const error=ref('');async function load(){error.value='';try{[infra.value,metrics.value]=await Promise.all([getInfrastructure(),getRuntimeMetrics()])}catch(e){error.value=(e as Error).message}}function tone(s:string){return s==='up'?'success':s==='down'?'danger':s==='skipped'?'warning':'info'}onMounted(load)</script>
<template><div class="infra-page"><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="surface infra-surface"><header><div><p>Live dependency probes</p><h2>基础设施状态</h2></div><el-tag effect="plain">{{infra?.acceptance??'loading'}}</el-tag></header><div class="service-grid"><article v-for="service in infra?.services??[]" :key="service.name"><el-tag :type="tone(service.status)" effect="plain">{{service.status}}</el-tag><div><strong>{{service.name}}</strong><p>{{service.latency_ms!==undefined?`${service.latency_ms} ms`:service.error??'未执行真实探测'}}</p></div></article></div></section><section class="surface infra-surface"><header><div><p>Runtime observations</p><h2>运行指标</h2></div></header><div class="metrics-ledger"><article><span>Counters</span><pre>{{JSON.stringify(metrics?.counters??{},null,2)}}</pre></article><article><span>Gauges</span><pre>{{JSON.stringify(metrics?.gauges??{},null,2)}}</pre></article><article><span>Observations</span><pre>{{JSON.stringify(metrics?.observations??{},null,2)}}</pre></article></div></section></div></template>
<style scoped>.infra-page{display:grid;gap:16px}.infra-surface{padding:20px}.infra-surface header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.infra-surface header p{color:var(--color-muted);font-size:12px;margin-bottom:4px}.infra-surface h2{font-size:19px}.service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--color-border);border:1px solid var(--color-border)}.service-grid article{background:#fff;padding:15px;display:flex;gap:12px;align-items:flex-start}.service-grid strong{display:block}.service-grid p{margin-top:5px;color:var(--color-muted);font-size:12px}.metrics-ledger{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metrics-ledger article{background:#f7f9fa;border:1px solid var(--color-border-soft);padding:14px;min-width:0}.metrics-ledger span{font-size:12px;font-weight:800}.metrics-ledger pre{margin-top:10px;overflow:auto;font-size:11px;line-height:1.5}@media(max-width:760px){.service-grid,.metrics-ledger{grid-template-columns:1fr}}</style>
